import{_ as p,a0 as r,w as a,s as l,ao as u,I as i,x as n,a1 as o,A as s}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const _=JSON.parse('{"title":"Linux有問必答：如何強制在下次登錄Linux時更換密碼 | LCTT x X-CMD","titleTemplate":false,"description":"Linux有問必答：如何強制在下次登錄Linux時更換密碼 | LCTT (201510) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux有問必答：如何強制在下次登錄Linux時更換密碼 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux有問必答：如何強制在下次登錄Linux時更換密碼 | LCTT (201510) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201510/20151012 Linux FAQs with Answers--How to force password change at the next login on Linux","title":"Linux有問必答：如何強制在下次登錄Linux時更換密碼","tag":"201510","desc":""},"relativePath":"201510/20151012 Linux FAQs with Answers--How to force password change at the next login on Linux.md","filePath":"[post].md"}'),d={name:"201510/20151012 Linux FAQs with Answers--How to force password change at the next login on Linux.md"};function x(m,t,g,f,L,w){const e=r("Link");return a(),l("div",null,[t[16]||(t[16]=u(`<h1 id="linux有問必答-如何強制在下次登錄linux時更換密碼" tabindex="-1">Linux有問必答：如何強制在下次登錄Linux時更換密碼 <a class="header-anchor" href="#linux有問必答-如何強制在下次登錄linux時更換密碼" aria-label="Permalink to “Linux有問必答：如何強制在下次登錄Linux時更換密碼”">​</a></h1><blockquote><p><strong>提問</strong>：我管理着一台多人共享的Linux服務器。我剛使用默認密碼創建了一個新用户，但是我想用户在第一次登錄時更換密碼。有沒有什麼方法可以讓他/她在下次登錄時修改密碼呢？</p></blockquote><p>在多用户Linux環境中，標準實踐是使用一個默認的隨機密碼創建一個用户賬户。成功登錄後，新用户自己改變默認密碼。出於安全考慮，經常建議“強制”用户在第一次登錄時修改密碼來確保這個一次性使用的密碼不會再被使用。</p><p>下面是<strong>如何強制用户在下次登錄時修改他/她的密碼</strong>。</p><p>每個Linux用户都關聯這不同的密碼相關配置和信息。比如，記錄着上次密碼更改的日期、最小/最大的修改密碼的天數、密碼何時過期等等。</p><p>一個叫chage的命令列工具可以訪問並調整密碼過期相關配置。你可以使用這個工具來強制用户在下次登錄修改密碼、</p><p>要查看特定用户的過期信息（比如：alice），運行下面的命令。注意的是除了你自己之外查看其他任何用户的密碼信息都需要root權限。</p><pre><code>$ sudo chage -l alice 
</code></pre><p><img src="https://c1.staticflickr.com/1/727/21955581605_5471e61ee0_c.jpg" alt=""></p><h3 id="強制用户修改密碼" tabindex="-1">強制用户修改密碼 <a class="header-anchor" href="#強制用户修改密碼" aria-label="Permalink to “強制用户修改密碼”">​</a></h3><p>如果你想要強制用户去修改他/她的密碼,使用下面的命令。</p><pre><code>$ sudo chage -d0 &lt;user-name&gt; 
</code></pre><p>原本<code>-d &lt;N&gt;</code>參數是用來設置密碼的“年齡”（也就是上次修改密碼起到1970/1/1起的天數）。因此“-d0”的意思是上次密碼修改的時間是1970/1/1，這就讓當前的密碼過期了，也就強制讓他在下次登錄的時候修改密碼了。</p><p>另外一個過期當前密碼的方式是用passwd命令。</p><pre><code>$ sudo passwd -e &lt;user-name&gt; 
</code></pre><p>上面的命令和“chage -d0”作用一樣，讓當前用户的密碼立即過期。</p><p>現在檢查用户的信息，你會發現：</p><p><img src="https://c2.staticflickr.com/6/5770/21767501480_ba88f00d80_c.jpg" alt=""></p><p>當你再次登錄時候，你會被要求修改密碼。你會在修改前被要求再驗證一次當前密碼。</p><p><img src="https://c2.staticflickr.com/6/5835/21929638636_eed4d69cb9_c.jpg" alt=""></p>`,20)),i("p",null,[t[1]||(t[1]=n("要設置更全面的密碼策略（如密碼複雜性，防止重複使用），則可以使用PAM。參見",-1)),o(e,{href:"http://xmodulo.com/set-password-policy-linux.html"},{default:s(()=>[...t[0]||(t[0]=[n("這篇文章",-1)])]),_:1}),t[2]||(t[2]=n("瞭解更多詳情。",-1))]),t[17]||(t[17]=i("hr",null,null,-1)),i("p",null,[t[4]||(t[4]=n("via: ",-1)),o(e,{href:"http://ask.xmodulo.com/force-password-change-next-login-linux.html"},{default:s(()=>[...t[3]||(t[3]=[n("http://ask.xmodulo.com/force-password-change-next-login-linux.html",-1)])]),_:1})]),i("p",null,[t[8]||(t[8]=n("作者：",-1)),o(e,{href:"http://ask.xmodulo.com/author/nanni"},{default:s(()=>[...t[5]||(t[5]=[n("Dan Nanni",-1)])]),_:1}),t[9]||(t[9]=n(" 譯者：",-1)),o(e,{href:"https://github.com/geekpi"},{default:s(()=>[...t[6]||(t[6]=[n("geekpi",-1)])]),_:1}),t[10]||(t[10]=n(" 校對：",-1)),o(e,{href:"https://github.com/wxy"},{default:s(()=>[...t[7]||(t[7]=[n("wxy",-1)])]),_:1})]),i("p",null,[t[13]||(t[13]=n("本文由 ",-1)),o(e,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...t[11]||(t[11]=[n("LCTT",-1)])]),_:1}),t[14]||(t[14]=n(" 原創編譯，",-1)),o(e,{href:"https://linux.cn/"},{default:s(()=>[...t[12]||(t[12]=[n("Linux中國",-1)])]),_:1}),t[15]||(t[15]=n(" 榮譽推出",-1))])])}const k=p(d,[["render",x]]);export{_ as __pageData,k as default};
